T['rows'] = [["Modell: gemeinsame Größen"], ["g, h", "9.81 m/s², 10 m", "Erdbeschleunigung; Fallhöhe von der Platte bis zum tiefsten Punkt der Kugel"], ["M", "1 kg", "Masse jeder Kugel, gleichmäßig auf ihre Teilchen verteilt"], ["Δt, t<sub>end</sub>", "2×10⁻⁴ s, 9 s", "Zeitschritt (Eisen wird in 5 Teilschritten gerechnet, Baumwolle in 2, aus Stabilitätsgründen); Dauer des Ablaufs; Positionen werden für die Wiedergabe alle 1 ms bis 2.5 s und danach alle 2 ms gespeichert"], ["Integrator", "semi-implizites Euler-Verfahren", "neue Geschwindigkeit aus den Kräften, dann neue Position aus der neuen Geschwindigkeit"], ["Modell: Eisen"], ["N, a", "91, 0.10 m", "Anzahl der Atome auf einem Dreiecksgitter; Gitterabstand"], ["k, αr<sub>0</sub>", "10⁵ N/m, 3.95", "Steifigkeit der Morse-Bindung in Ruhe (k = 2Dα²) und Form (die des Eisens, nach Girifalco und Weizer)"], ["c", "2 N·s/m", "Dämpfer der Bindung, steht für innere Reibung"], ["Modell: Baumwolle"], ["Fasern × Perlen, s", "18 × 34, 0.08 m", "Fasern, Perlen je Faser, Perlenabstand (612 Perlen)"], ["k<sub>ax</sub>, c", "300 N/m, 0.3 N·s/m", "Dehnungsfeder entlang einer Faser und ihr Dämpfer"], ["κ, c<sub>b</sub>", "0.25 N·m/rad, 0.004 N·m·s/rad", "Biegefeder auf den Winkel zwischen Segmenten (Ruhewinkel = natürliche Krümmung) und Biegereibung"], ["k<sub>j</sub>, F<sub>j</sub>", "40 N/m, 4 N", "Kreuzungsstelle der Fasern: Morse-Tal mit dieser Steifigkeit und dieser größten Zugkraft; bricht bei der dreifachen Dehnung, bei der die Zugkraft am größten ist"], ["d<sub>c</sub>, k<sub>c</sub>, c<sub>c</sub>", "0.06 m, 20 N/m, 0.4 N·s/m", "Kontakt Faser–Faser: Reichweite, Abstoßungssteifigkeit, Reibung beim Aneinanderreiben"], ["Modell: Kopf und Waage"], ["m<sub>p</sub>, k<sub>h</sub>, c<sub>h</sub>", "0.2 kg, 6000 N/m, 62 N·s/m", "Masse der Platte, Feder des Kopfes, Dämpfer des Kopfes"], ["ω<sub>c</sub>, ζ<sub>c</sub>", "1350 rad/s, 0.5", "Hautkontakt zwischen einem Teilchen und der Platte: Jedes Teilchen prallt mit dieser Kreisfrequenz und diesem Dämpfungsgrad zurück (ζ = 1 ist die Grenze zwischen Zurückprallen und schleichendem Zurückkehren)"], ["Anzeige", "F = k<sub>h</sub> × Stauchung", "was die Waage zeigt; das Gewicht ist der Mittelwert der Anzeige ab 4 s, ab 6.5 s angezeigt; Masse = Gewicht / g"], ["Abschätzungen für die reale Welt"], ["m, h", "0.5 kg, 10 m", "Masse der Kugel, Fallhöhe"], ["ρ", "7870, 1520, 30 kg/m³", "Eisen, Cellulose, lose Baumwollwatte (der Wert für Baumwolle ist meine Annahme)"], ["ρ<sub>air</sub>, C<sub>d</sub>", "1.2 kg/m³, 0.47", "Luftdichte, Widerstandsbeiwert einer Kugel"], ["k<sub>air</sub>", "0, 1, 4, 16", "Widerstand als Vielfaches echter Luft, aus dem Menü „Luft“"], ["ρ<sub>Fe</sub>, ρ<sub>c</sub>", "7874, 30 kg/m³", "Dichten von echtem Eisen und von loser Watte: mit Luft ergeben sie die Querschnitte A echter 1-kg-Kugeln, 30.6 cm² und 1252 cm²"], ["k<sub>h</sub>", "4.0 MN/m", "mittlere dynamische Schädelsteifigkeit, Yoganandan u. a."], ["M<sub>h</sub>", "4.5 kg", "Masse eines Kopfes, angenommener typischer Wert"], ["E", "210 GPa, ~10 GPa", "Elastizitätsmodul von Eisen; von Cellulose (gerundet, angenommen)"], ["D, α, r<sub>0</sub>", "0.4174 eV, 1.3885 Å⁻¹, 2.845 Å", "Morse-Parameter von Eisen, Girifalco und Weizer (1959)"]]
T['h_src'] = "Quellen"
T['sources'] = ["L. A. Girifalco, V. G. Weizer, „Application of the Morse potential function to cubic metals“, Phys. Rev. 114, 687 (1959). <a href=\"https://doi.org/10.1103/PhysRev.114.687\">doi:10.1103/PhysRev.114.687</a>; Modelleintrag: <a href=\"https://www.ctcms.nist.gov/potentials/entry/1959--Girifalco-L-A-Weizer-V-G--Fe\">NIST Interatomic Potentials Repository</a>. Die Eisenwerte stammen aus meiner Erinnerung an die Tabelle der Arbeit; ich konnte die Tabelle online nicht einsehen.", "M. S. Daw, M. I. Baskes, „Embedded-atom method“, Phys. Rev. B 29, 6443 (1984). <a href=\"https://link.aps.org/doi/10.1103/PhysRevB.29.6443\">Link</a>", "N. Yoganandan u. a., Biomechanik des menschlichen Kopfes unter quasistatischer und dynamischer Belastung (Versuche an Leichen; mittlere dynamische Bruchlast 11.9 kN, Steifigkeit 4023 N/mm). <a href=\"https://wbldb.lievers.net/10149876.html\">Zusammenfassung</a>", "C. M. van Wyk, „A study of the compressibility of wool“, Onderstepoort J. Vet. Sci. 21, 99 (1946). <a href=\"https://repository.up.ac.za/handle/2263/59727\">Repositorium</a>", "Diskrete Fasernetzwerk-Modelle von Papier, Chalmers University of Technology. <a href=\"https://research.chalmers.se/en/publication/532887\">Link</a>"]
